 const doc=await store.read();doc.latestCollection={capturedAt:at,sheet:'Sheet1',quality:{passed:true},products:sources};doc.current={capturedAt:at,products:sources,mappingRows:mapping};doc.mappingRows=mapping;doc.sourceChanges={schemaVersion:1,report,history:[report],tasks,reviewHistory:[],priceTasksVersion:1};await writeJSON(store.file,doc);
